$ErrorActionPreference='Stop';$P=Split-Path -Parent $MyInvocation.MyCommand.Path;if(-not(Test-Path 'angular.json')){throw 'Run from Angular frontend root.'};$B=".phase-a4.6-backup-$(Get-Date -Format yyyyMMdd-HHmmss)";New-Item -ItemType Directory -Force $B|Out-Null;Copy-Item 'src\app\app.routes.ts' $B;Copy-Item 'src\app\features\admin\content\work-workspace' (Join-Path $B 'work-workspace') -Recurse -Force
Copy-Item (Join-Path $P 'payload\src\*') 'src' -Recurse -Force
powershell -ExecutionPolicy Bypass -File (Join-Path $P 'PATCH.ps1')
$r=Get-Content 'src\app\app.routes.ts' -Raw;$route="{ path: 'content/lessons/:id', title: 'Lesson Editor | The Esoteric Library', loadComponent: () => import('./features/admin/content/lesson-editor/admin-lesson-editor').then((m) => m.AdminLessonEditor) },";$anchor="{ path: 'content/works/:id',";if($r -notmatch "path: 'content/lessons/:id'"){$r=$r -replace [regex]::Escape($anchor),($route+"`r`n      "+$anchor)};Set-Content 'src\app\app.routes.ts' $r
function Run-Step([string]$Name,[scriptblock]$Command){Write-Host "Running $Name..." -ForegroundColor Cyan;&$Command;if($LASTEXITCODE -ne 0){throw "$Name failed: $LASTEXITCODE"}};Run-Step 'format'{npm run format};Run-Step 'build'{npm run build};Run-Step 'tests'{npm test -- --watch=false};Write-Host 'Phase A4.6 installed successfully.' -ForegroundColor Green;Write-Host "Backup: $B"
